CREATE TABLE IF NOT EXISTS folders(id UUID PRIMARY KEY,owner_id UUID NOT NULL REFERENCES users(id),parent_id UUID REFERENCES folders(id) ON DELETE CASCADE,name VARCHAR(255) NOT NULL,full_path TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,UNIQUE(owner_id,parent_id,name));
CREATE TABLE IF NOT EXISTS file_metadata(id UUID PRIMARY KEY,owner_id UUID NOT NULL REFERENCES users(id),folder_id UUID REFERENCES folders(id) ON DELETE SET NULL,filename VARCHAR(1024) NOT NULL,mime_type VARCHAR(255) NOT NULL,size_bytes BIGINT NOT NULL,content_hash VARCHAR(64),encryption_key_ref VARCHAR(100),status VARCHAR(20) NOT NULL,tags TEXT[] NOT NULL DEFAULT '{}',expected_chunks INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_file_hash ON file_metadata(content_hash);CREATE INDEX IF NOT EXISTS idx_file_owner_folder ON file_metadata(owner_id,folder_id);CREATE INDEX IF NOT EXISTS idx_file_search ON file_metadata USING GIN(to_tsvector('simple'::regconfig,filename||' '||mime_type));CREATE INDEX IF NOT EXISTS idx_file_tags ON file_metadata USING GIN(tags);
